export interface TablePlusParams {
    page: number;
    pageSize: number;
    keyword: string;
    sorting: SortingState;
    filters: ColumnFiltersState;
    query: Record<string, unknown>;
}

export interface SavedTableView {
    name: string;
    sorting: SortingState;
    filters: ColumnFiltersState;
    query: Record<string, unknown>;
    keyword: string;
    columns?: {
        visibility: VisibilityState;
        order: string[];
        pinning: ColumnPinningState;
        sizing: ColumnSizingState;
    };
}

export interface TableBatchAction<T> {
    key: string;
    label: string;
    destructive?: boolean;
    onAction: (keys: string[], records: T[], signal: AbortSignal) => void | Promise<void>;
}

export interface TablePlusProps<T> extends Omit<DataTableProps<T>, 'data'> {
    data?: T[];
    title?: string;
    description?: string;
    request?: (params: TablePlusParams, signal: AbortSignal) => Promise<{
        data: T[];
        total: number;
    }>;
    onCreate?: () => void;
    createLabel?: string;
    queryFields?: FormPlusField[];
    views?: SavedTableView[];
    loadViews?: (signal: AbortSignal) => Promise<SavedTableView[]>;
    saveView?: (view: SavedTableView, signal: AbortSignal) => Promise<void>;
    deleteView?: (name: string, signal: AbortSignal) => Promise<void>;
    showViews?: boolean;
    batchActions?: TableBatchAction<T>[];
    onSelectedKeysChange?: (keys: string[]) => void;
}

export interface DataTableProps<T> {
    data: T[];
    columns: ColumnDef<T, any>[];
    getRowId?: (row: T, index: number) => string;
    getSubRows?: (row: T) => T[] | undefined;
    selection?: boolean;
    searchable?: boolean;
    toolbar?: React.ReactNode;
    pagination?: boolean;
    pageSize?: number;
    virtual?: boolean;
    virtualColumns?: boolean;
    height?: number;
    loading?: boolean;
    error?: string;
    onRetry?: () => void;
    className?: string;
    density?: 'comfortable' | 'compact';
    onDataChange?: (rows: T[]) => void;
    onCellEdit?: (row: T, columnId: string, value: unknown) => void;
    onSelectionChange?: (rows: T[]) => void;
    rowExpansion?: (row: T) => React.ReactNode;
    getCellProps?: (row: T, columnId: string, index: number) => Partial<CellSpan> | undefined;
    tableOptions?: Partial<Omit<TableOptions<T>, 'data' | 'columns' | 'getCoreRowModel'>>;
    exportName?: string;
    caption?: string;
    storageKey?: string;
    reorderable?: boolean;
    onRowOrderChange?: (rows: T[]) => void;
    summary?: (rows: T[]) => React.ReactNode;
}

export interface EditableColumnMeta {
    editable?: boolean;
    inputType?: 'text' | 'number' | 'date' | 'email';
    validate?: (value: unknown) => string | undefined;
}

export function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }): React.JSX.Element

export interface InputProps extends Omit<React.ComponentProps<'input'>, 'prefix'> {
    leading?: React.ReactNode;
    trailing?: React.ReactNode;
    allowClear?: boolean;
    showCount?: boolean;
    passwordToggle?: boolean;
    onValueChange?: (value: string) => void;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]

export function CheckboxGroup({
  options,
  value = [],
  onValueChange,
  disabled,
  label,
}: {
  options: { value: string; label: React.ReactNode; disabled?: boolean }[]
  value?: string[]
  onValueChange?: (value: string[]) => void
  disabled?: boolean
  label?: string
}): React.JSX.Element

export function PopoverContent({
  className,
  align = 'center',
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>): React.JSX.Element

export interface UIConfig {
    density: 'comfortable' | 'compact';
    direction: 'ltr' | 'rtl';
    locale: string;
}

export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
    density?: UIConfig['density'];
    direction?: UIConfig['direction'];
    locale?: string;
    accent?: string;
    radius?: number;
}

export interface TableView {
    visibility: Record<string, boolean>;
    order: string[];
    pinning: {
        left: string[];
        right: string[];
    };
    sizing: Record<string, number>;
}

export interface CellSpan {
    rowSpan: number;
    colSpan: number;
}

export interface FormPlusField<T extends FieldValues = FieldValues> {
    name: FieldPath<T>;
    label: string;
    type?: FieldValueType;
    placeholder?: string;
    description?: string;
    required?: boolean;
    rules?: ControllerProps<T>['rules'];
    options?: SelectOption[];
    colSpan?: number;
    step?: number;
    hidden?: (values: T) => boolean;
    disabled?: boolean;
    dependencies?: FieldPath<T>[];
    loadOptions?: (values: T, signal: AbortSignal) => Promise<SelectOption[]>;
    render?: (props: {
        value: any;
        onChange: (value: any) => void;
        invalid: boolean;
        id: string;
    }) => React.ReactNode;
}

export interface FormPlusProps<T extends FieldValues = FieldValues> {
    fields: FormPlusField<T>[];
    defaultValues?: DefaultValues<T>;
    onSubmit: (values: T) => void | Promise<void>;
    onValuesChange?: (values: DeepPartial<T>) => void;
    resolver?: Resolver<T>;
    submitLabel?: string;
    columns?: 1 | 2 | 3;
    className?: string;
    children?: React.ReactNode;
    steps?: string[];
    resettable?: boolean;
    disabled?: boolean;
    scrollToError?: boolean;
}

export function LoginForm<T extends FieldValues = FieldValues>({
  fields,
  ...props
}: Omit<FormPlusProps<T>, 'fields'> & { fields?: FormPlusField<T>[] }): React.JSX.Element

export function FormPlusList({
  name,
  label = 'Items',
  fields,
  defaultItem = {},
}: {
  name: string
  label?: string
  fields: { name: string; placeholder?: string }[]
  defaultItem?: Record<string, string>
}): React.JSX.Element

export interface OverlayFormProps<T extends FieldValues = FieldValues> extends FormPlusProps<T> {
    title: string;
    description?: string;
    trigger: React.ReactNode;
    open?: boolean;
    onOpenChange?: (open: boolean) => void;
}

export function QueryFilter<T extends FieldValues = FieldValues>({
  fields,
  visibleCount = 3,
  ...props
}: FormPlusProps<T> & { visibleCount?: number }): React.JSX.Element

export function LightFilter<T extends FieldValues = FieldValues>({
  triggerLabel = 'Filter records',
  onSubmit,
  ...props
}: FormPlusProps<T> & { triggerLabel?: string }): React.JSX.Element

export interface FieldPlusProps {
    type?: FieldValueType;
    value?: unknown;
    onValueChange?: (value: any) => void;
    mode?: 'read' | 'edit';
    options?: SelectOption[];
    placeholder?: string;
    disabled?: boolean;
    id?: string;
    label?: string;
    currency?: string;
    locale?: string;
    invalid?: boolean;
    treeNodes?: TreeNode[];
